import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { ZimmProductName } from 'app/components/ui-kits/atoms/zimmProductName';
import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';

const ZIMM_PRODUCT_CONTENT_RECIPE = 'ZimmProductContent';

type ZimmProductContentProps = {
  /** The product's display name. */
  name: string;
  /**
   * Heading level for the name. Passed through rather than fixed here so the caller keeps
   * control of the page's heading outline — see `ZimmProductName`.
   */
  headingLevel: 'h1' | 'h2' | 'h3';
  /**
   * Price, already formatted for the storefront's locale and currency by the caller. Optional
   * for the same reason as `description`: `ZimmProductPrice` renders nothing when the value is
   * absent or empty, so the group's `gap` collapses to whatever actually rendered.
   */
  price?: string;
  /** Long description as authored in Business Manager. Omitted when the product has none. */
  description?: string;
};

/**
 * Molecule — the PDP text group: name, price, description.
 *
 * Model copy and the style code are deliberately *not* here. The design places them at the
 * bottom of the column, after the accordions, so the page positions them itself rather than
 * this molecule holding them and then having to unpick the order.
 */
export const ZimmProductContent = ({ name, headingLevel, price, description }: ZimmProductContentProps) => {
  const styles = useStyleConfig(ZIMM_PRODUCT_CONTENT_RECIPE, {});

  return (
    <chakra.div __css={styles} data-testid="product-content">
      <ZimmProductName name={name} as={headingLevel} />
      <ZimmProductPrice price={price} />
=== rest of that story ===
      </Box>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductContent>;

export const Default: Story = {
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: REAL_DESCRIPTION,
  },
};

export const WithoutDescription: Story = {
  name: 'Without description — rhythm collapses',
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: undefined,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const root = canvas.getByTestId('product-content');

    // The description atom returns null, so the group must be exactly two rows with no
    // trailing gap. A per-child marginBottom would leave 20px hanging under the price.
    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
    await expect(root.children).toHaveLength(2);

    // A flex gap applies only between rendered items, so two children means exactly one gap
    // and no trailing space under the price.
    await expect(getComputedStyle(root).rowGap).toBe('20px');
  },
};

export const RhythmWithDescription: Story = {
  name: 'Rhythm — 20px between every row',
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: '<p>A long sleeve linen mini dress.</p>',
  },
  play: async ({ canvasElement }) => {
    const root = within(canvasElement).getByTestId('product-content');
    await expect(root.children).toHaveLength(3);

    // 20px = spacing.l, asserted as a computed value so a change to the token, to the recipe,
    // or to its registration in theme/components/index.ts all surface here rather than only in
    // a visual review. It also pins down that no child can out-specify the container.
    await expect(getComputedStyle(root).rowGap).toBe('20px');
    for (const child of Array.from(root.children)) {
      await expect(getComputedStyle(child).marginTop).toBe('0px');
    }
  },
};

export const BlankDescription: Story = {
  name: 'Description present but empty — also collapses',
  // Business Manager can save the field as empty markup rather than clearing it, which is not
  // the same input as `undefined` and has to reach the same rendering.
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '$795.00',
    description: '<p></p>',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByTestId('product-content').children).toHaveLength(2);
    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
  },
};

export const WithoutPrice: Story = {
  name: 'Price absent — the price row collapses too',
  // Not a hypothetical: the page's mapper resolves a product with no price data to `''` rather
  // than to a formatted NaN, and that empty string reaches ZimmProductPrice unchanged.
  args: {
    name: 'Natura Mini Dress',
    headingLevel: 'h1',
    price: '',
    description: '<p>A long sleeve linen mini dress.</p>',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const root = canvas.getByTestId('product-content');

    // The middle row is the one that disappears here, so this also pins down that the rhythm
    // is a container `gap` and not a per-child margin — a margin on the name would leave the
    // 20px hanging above a price that is no longer there.
    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
    await expect(canvas.getByTestId('product-name')).toBeInTheDocument();
    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
    await expect(getComputedStyle(root).rowGap).toBe('20px');
  },
};

