import { useIntl } from 'react-intl';
import { Skeleton, VStack } from '@salesforce/retail-react-app/app/components/shared/ui';
import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';

/*
 * `app/...`, not `@salesforce/retail-react-app/app/...`, for the two overridden modules below.
 * pwa-kit-dev's OverridesResolverPlugin skips any request whose issuer already lives in
 * `overrides/` (its `isFromExtends` guard), so a base-path import from this file would resolve
 * to the *base* component even in the real app build — the same reason the page's own
 * `product-view` import is relative. `Breadcrumb`, `PromoCallout` and `shared/ui` above have no
 * override, so the base path is the correct one for them.
 */
import type { ProductViewHeaderProps } from 'app/components/product-view';
import { ZimmProductContent } from 'app/components/ui-kits/molecules/zimmProductContent';
import { selectPdpProductInfo } from '../productInfo';

/**
 * Replaces the title/price block of ProductView's header with the Zimmermann content group.
 *
 * The breadcrumb and promo callout are reproduced from the base header rather than dropped:
 * `renderHeader` replaces the whole header block, and neither of those belongs to SFCC-89
 * (breadcrumb is SFCC-578, badges are SFCC-132/225), so losing them here would be a
 * regression rather than a scope decision.
 *
 * ProductView renders this once per breakpoint, so it stays free of side effects.
 *
 * A component rather than the bare render function it was on the page, so that it can hold
 * `useIntl()` itself — `formatPrice` needs `formatNumber`. components.md exempts `useIntl` from
 * the container/presentational rule because it reads a Provider mounted above the route tree,
 * and this keeps the prop surface exactly `ProductViewHeaderProps`, which passing `formatPrice`
 * in would have widened. `useIntl()` throws without an `IntlProvider`, so anything rendering
 * this must supply one: the app does in the base `_app`, `.storybook/preview.tsx` does for the
 * stories.
 */
export const StaticProductHeader = ({
  name,
  product: headerProduct,
  priceData,
  currency,
  category: headerCategory,
  isProductPartOfBundle,
}: ProductViewHeaderProps) => {
  const { formatNumber } = useIntl();

  // The page keeps its own copy of this for the meta block it renders below the accordions,
  // which is outside this header — so that one is not a leftover of this extraction.
  const formatPrice = (amount: number, priceCurrency: string) =>
    formatNumber(amount, { style: 'currency', currency: priceCurrency });

  const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);

