import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { MemoryRouter } from 'react-router-dom';
import { Box } from '@chakra-ui/react';
import { expect, within } from 'storybook/test';
import { StaticProductHeader } from './staticProductHeader';

/*
 * A reasoned deviation from components.md's "Pages get a story showing the full assembly with
 * representative props — not a story per sub-section", declared in the PR body rather than
 * presented as compliance. Storying the PDP itself would mean stubbing ~30 hook call sites
 * including `useProduct`, which cuts against the direction to prefer real SFCC data; #59 set
 * the precedent of storying the presentational `Footer` rather than the fetching container.
 */

/** Real Shopper Products fields for 8637DS241 (ZimmermannAU, 2026-08-23). */
const PRODUCT = {
  id: '8637DS241-BLUEB-6',
  name: 'Natura Long Sleeve Linen Mini Dress',
  longDescription:
    '<p>A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.</p>',
  master: { masterId: '8637DS241' },
  c_modelFit: 'Model is 178cm / 5ft 10in and wears a size 1.',
  price: 795,
  productPromotions: [{ promotionId: 'final-sale', calloutMsg: 'Final sale — no returns' }],
};

const meta: Meta<typeof StaticProductHeader> = {
  title: 'Commerce/StaticProductHeader',
  component: StaticProductHeader,
  argTypes: {
    name: { control: 'text' },
    currency: { control: 'text' },
    isProductPartOfBundle: { control: 'boolean' },
  },
  decorators: [
    (Story: React.ComponentType) => (
      // MemoryRouter because the base `Breadcrumb` renders react-router `Link`s, which throw
      // outside a Router — preview.tsx supplies Chakra and IntlProvider, but no Router.
      // 218px is the DS info-column width, the same frame zimmProductContent's story uses, so
      // the name's wrap behaviour here matches the real column.
      <MemoryRouter>
        <Box width="218px">
          <Story />
        </Box>
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof StaticProductHeader>;

export const Default: Story = {
  name: 'Full product — everything renders',
  args: {
    name: PRODUCT.name,
    product: PRODUCT,
    priceData: { currentPrice: 795 },
    currency: 'AUD',
    category: [
      { id: 'womens', name: 'Womens' },
      { id: 'womens-clothing-dresses', name: 'Dresses' },
    ],
    isProductPartOfBundle: false,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // h2, not h1: the page owns the h1 (a screen-reader-only "Product Details"), so this is
    // the constraint the extraction had to preserve rather than quietly re-level.
    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();

    // Breadcrumb and promo callout are reproduced from the base header rather than dropped,
    // because `renderHeader` replaces the whole block — assert both survived the move.
    await expect(canvas.getByRole('link', { name: 'Dresses' })).toBeInTheDocument();
    await expect(canvas.getByTestId('promo-callout')).toBeInTheDocument();

    // Formatted by the partial's own `useIntl()`, under preview.tsx's en-AU IntlProvider.
    await expect(canvas.getByTestId('product-price')).toHaveTextContent('795');
    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
  },
};

export const NameOnly: Story = {
  name: 'Product absent, name present — price collapses',
  // ProductView passes `name: product?.name` alongside `product`, so during a variant fetch the
  // name can be known while the product is not. `headerProduct ?? { name }` is the path that
  // keeps the title rendered instead of dropping back to a skeleton.
  args: {
    name: PRODUCT.name,
    product: undefined,
    priceData: undefined,
    currency: 'AUD',
    isProductPartOfBundle: false,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();

    // No priceData means the mapper yields '' rather than a formatted NaN, and the price atom
    // renders nothing — so the group collapses to one row instead of reserving an empty one.
    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();

    // `product` is what gates the promo, so it stays a bare skeleton here.
    await expect(canvas.queryByTestId('promo-callout')).not.toBeInTheDocument();
  },
};

export const Loading: Story = {
  name: 'Neither — the state every page load starts in',
  args: {},
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // `selectPdpProductInfo` returns null without a name, so the content group is absent and
    // only the reserve is on screen.
    await expect(canvas.queryByTestId('product-content')).not.toBeInTheDocument();

    // The reserve itself (D17). An empty SFCC `Skeleton` measures 0px — its baseStyle sets only
    // borderRadius and opacity — so without the explicit minHeight the title would shove the
    // page down when it resolves. 18px is `lineHeights['2xs']` (1.125rem), which is what
    // `--zimm-font-lineheight-2xs` derives from and what ZimmProductName's heading3 renders at.
    // Asserted on the first skeleton by position because an empty one carries no accessible
    // name or test id to select it by, and adding one would change the page's rendered output.
    const reserve = canvasElement.querySelector('.chakra-skeleton');
    await expect(reserve).not.toBeNull();
    await expect(getComputedStyle(reserve as Element).minHeight).toBe('18px');
  },
};
